mapper.select:
SELECT P.PROJ_ID AS projId , P.PROJ_NM AS projNm , P.BILL_STEP AS billStep , P.BILL_STATUS AS billStatus , C.CUST_NM AS custNm , CONT.CONT_AMT AS totalAmt , P.BILL_STATUS AS billStatus , IFNULL(SUM(B.BILL_AMT), 0) AS totalBilledAmt , SUM(CASE WHEN B.ACTUAL_PAY_DT IS NOT NULL THEN B.BILL_AMT ELSE 0 END) AS totalPaidAmt , CASE WHEN CONT.CONT_AMT > 0 AND CONT.CONT_AMT = SUM(IFNULL(B.BILL_AMT, 0)) AND COUNT(B.BILL_ID) = SUM(CASE WHEN B.ACTUAL_PAY_DT IS NOT NULL THEN 1 ELSE 0 END) THEN 'Y' ELSE 'N' END AS isPaid FROM TB_PROJECT P LEFT JOIN TB_CONTRACT CONT ON P.CONT_ID = CONT.CONT_ID LEFT JOIN TB_SALES S ON CONT.SALES_ID = S.SALES_ID LEFT JOIN TB_CUSTOMER C ON S.CUST_ID = C.CUST_ID LEFT JOIN TB_BILLING B ON P.PROJ_ID = B.PROJ_ID AND B.DEL_YN = 'N' WHERE 1=1
AND P.PROJ_NM LIKE CONCAT('%', #{searchKeyword}, '%')
GROUP BY P.PROJ_ID, P.PROJ_NM, C.CUST_NM, CONT.CONT_AMT, P.BILL_STATUS ORDER BY P.PROJ_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
        INSERT INTO TB_BILLING (
              PROJ_ID
	        , BILL_TITLE
	        , BILL_AMT
	        , TAX_BILL_DT
	        , PAY_DT
	        , ACTUAL_PAY_DT
	        , BILL_REMARK
	        , LAST_UPDUSR_ID
        ) VALUES (
	          #{projId}
	        , #{billTitle}
	        , #{billAmt}
	        , NULLIF(#{taxBillDt}, '')
	        , NULLIF(#{payDt}, '')
	        , NULLIF(#{actualPayDt}, '')
	        , #{billRemark}
	        , #{lastUpdusrId}
        )

mapper.update:
UPDATE TB_BILLING
PROJ_ID = #{projId}, BILL_TITLE = #{billTitle}, BILL_AMT = #{billAmt}, TAX_BILL_DT = NULLIF(#{taxBillDt}, ''), PAY_DT = NULLIF(#{payDt}, ''), ACTUAL_PAY_DT = NULLIF(#{actualPayDt}, ''), BILL_REMARK = #{billRemark}, LAST_UPDUSR_ID = #{lastUpdusrId},
WHERE BILL_ID = #{billId}

UPDATE TB_BILLING
SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE BILL_ID = #{billId}

UPDATE TB_BILLING
   SET ACTUAL_PAY_DT = #{actualPayDt}
 WHERE BILL_ID = #{billId}

UPDATE TB_BILLING
   SET ATCH_FILE_ID = #{atchFileId}
 WHERE BILL_ID = #{billId}
